export default function input({ body, headers, expected, calendarId }) {
  if (!expected || headers.authorization !== expected) throw Error("Unauthorized");
  if (!calendarId || calendarId.includes("YOUR_")) throw Error("Configure calendar");
  const x = body,
    op = String(x.operation || ""),
    allowed = [
      "GET_CALENDAR",
      "GET_ALL_CALENDAR",
      "AVALIABILITY_CALENDAR",
      "CREATE_CALENDAR",
      "UPDATE_CALENDAR",
      "DELETE_CALENDAR",
    ];
  if (!allowed.includes(op)) throw Error("Unknown operation");
  const id = String(x.eventId || ""),
    requestId = String(x.requestId || "");
  if (
    ["CREATE_CALENDAR", "UPDATE_CALENDAR", "DELETE_CALENDAR"].includes(op) &&
    !/^[A-Za-z0-9_-]{1,100}$/.test(requestId)
  )
    throw Error("Unique requestId required");
  if (["GET_CALENDAR", "UPDATE_CALENDAR", "DELETE_CALENDAR"].includes(op) && !id)
    throw Error("Event ID required");
  if (
    ["CREATE_CALENDAR", "AVALIABILITY_CALENDAR"].includes(op) &&
    (!Number.isFinite(Date.parse(x.start)) ||
      !Number.isFinite(Date.parse(x.end)) ||
      Date.parse(x.end) <= Date.parse(x.start))
  )
    throw Error("Valid start/end required");
  const useDefault = Boolean(x.useDefault),
    event =
      op === "CREATE_CALENDAR"
        ? {
            start: { dateTime: x.start },
            end: { dateTime: x.end },
            description: String(x.description || ""),
            ...(useDefault ? {} : { reminders: { useDefault: false } }),
          }
        : useDefault
          ? {}
          : { reminders: { useDefault: false } };
  return {
    operation: op,
    calendarId,
    eventId: id || "not-applicable",
    key: "calendar-mcp:" + op + ":" + requestId,
    fingerprint: JSON.stringify({
      op,
      id,
      start: x.start,
      end: x.end,
      description: x.description,
      useDefault,
    }),
    after: x.after ? String(x.after) : null,
    before: x.before ? String(x.before) : null,
  };
}

