export default async function list({ calendarId, after, before }, ctx) {
  let pageToken = null,
    seen = new Set(),
    items = [];
  do {
    const page = await ctx.actions.call("googlecalendar.list_events", {
      calendarId,
      timeMin: after,
      timeMax: before,
      orderBy: "startTime",
      singleEvents: true,
      maxResults: 250,
      ...(pageToken ? { pageToken } : {}),
    });
    if (!Array.isArray(page.items)) throw Error("Invalid Calendar result");
    items.push(...page.items);
    pageToken = page.nextPageToken || null;
    if (pageToken && seen.has(pageToken)) throw Error("Repeated Calendar cursor");
    if (pageToken) seen.add(pageToken);
  } while (pageToken);
  return { body: JSON.stringify({ response: items }) };
}

