export default function f({ calendars, calendarId }) {
  const c = calendars[calendarId];
  if (!c || c.errors?.length || !Array.isArray(c.busy)) throw Error("Unknown availability");
  return { body: JSON.stringify({ response: { available: c.busy.length === 0 } }) };
}

