export default async function f({ key, fingerprint, result }, ctx) {
  if (!result) throw Error("Unknown Calendar result");
  await ctx.state.set(key, { status: "done", fingerprint });
  return { body: JSON.stringify({ response: { id: result, success: true } }) };
}

